template.inlineTemplate:
//LISTGRP  EXEC PGM=IKJEFT01,DYNAMNBR=36
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 LISTGRP ${instance-RACF_GROUP}
/*

//TSO1     EXEC PGM=IKJEFT01,DYNAMNBR=36,REGION=0M
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 EX '${instance-REXX_DATASET}(DORMANT)' '${instance-RACF_GROUP} ${instance-DORMANT_DAYS}'
/*

/* Approval gate. This step is intentionally a submittable REXX  */
/* so completing it leaves a durable audit record of who         */
/* authorised the revocation and when. A template is optional    */
/* here - an instruction-only manual step would gate the same    */
/* way via prereqStep - but the audit record is the reason we    */
/* keep it. The exec makes no RACF changes and exits 0.          */
SAY 'Approval gate acknowledged by' SYSVAR('SYSUID')
SAY 'Timestamp:' DATE() TIME()
EXIT 0

//TSO1     EXEC PGM=IKJEFT01,DYNAMNBR=36,REGION=0M
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 EX '${instance-REXX_DATASET}(DORMANT)' '${instance-RACF_GROUP} ${instance-DORMANT_DAYS} REVOKE'
/*
